 destroyArm(index){const arm=this.model.arms[index],point=this.model.weakPointPosition(index?'arm-right':'arm-left');arm.visible=false;this.model.anchor=null;for(const section of this.sections){let node=section.node;while(node&&node!==arm)node=node.parent;if(node===arm)section.hidden=section.collisionDisabled=true;}for(const [i,launcher]of this.model.launchers.entries()){let node=launcher;while(node&&node!==arm)node=node.parent;if(node===arm){this.state.launchers[i].health=0;this.state.launchers[i].destroyed=true;}}if(this.state.launchers[this.config.rain.module].destroyed){if(this.rain)this.rain.pending=[];this.beamWalls?.reset();}this.effects?.impact(point,'#ff8b38',8);this.onEvent((index?'RIGHT':'LEFT')+' ARM DESTROYED · attached weapons disabled.');}
 modifyDamage(power,point,part){if(part==='arm-left'||part==='arm-right'){const i=part==='arm-left'?0:1;if(this.armsHealth[i]<=0)return 0;const damage=Math.min(this.armsHealth[i],Math.max(0,power));this.armsHealth[i]-=damage;this.feedback=(i?'RIGHT':'LEFT')+' ARM HIT';this.effects?.impact(point,'#ff9e42');if(this.armsHealth[i]===0)this.destroyArm(i);return damage*this.config.weakPoints.armBossDamageScale;}if(part==='back'){this.feedback='BACK REACTOR HIT';this.effects?.impact(point,'#ff9e42');return power*this.config.weakPoints.backDamageMultiplier*this.state.multiplier(this.attackKey);}this.feedback='ARMOUR · AIM FOR ARM CORES OR BACK REACTOR';return 0;}
 interrupt(seconds=1){if(this.dead)return false;this.stunRemaining=Math.max(this.stunRemaining,seconds);this.onEvent('Bastion interrupted · armour locked briefly.');return true;}
